import shutil
import subprocess
from pathlib import Path

from agents import function_tool


@function_tool
def archive_and_run_migration(
    migration_file: str,
    db_path: str,
    pending_dir: str,
    applied_dir: str,
) -> str:
    src = Path(pending_dir) / migration_file
    dst_dir = Path(applied_dir)
    dst = dst_dir / migration_file

    if not src.is_file():
        return "error: migration not found: %s" % src
    if not Path(db_path).is_file():
        return "error: database not found: %s" % db_path
    if dst.exists():
        return "error: already applied: %s" % dst

    dst_dir.mkdir(parents=True, exist_ok=True)
    moved = shutil.move(str(src), str(dst))

    try:
        p = subprocess.run(
            ["sqlite3", db_path, ".read %s" % moved],
            capture_output=True,
            text=True,
            timeout=300,
        )
    except subprocess.TimeoutExpired:
        return "error: migration timed out, file moved to %s" % moved

    out = p.stdout.strip()
    err = p.stderr.strip()
    if p.returncode != 0:
        return "failed (exit %d), file moved to %s: %s" % (p.returncode, moved, err)
    return "ok, moved to %s. output: %s" % (moved, out or "(none)")

import sqlite3

import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("db-capacity")

INVENTORY_DB_PATH = "/var/lib/dbadmin/inventory.db"


@mcp.tool()
def purchase_provisioned_iops_and_update_instance(
    instance_identifier: str,
    additional_iops: int,
    customer_id: str,
    price_per_iops_cents: int,
) -> dict:
    if additional_iops <= 0:
        return {"success": False, "error": "additional_iops must be positive"}

    inventory_connection = sqlite3.connect(INVENTORY_DB_PATH)
    inventory_connection.row_factory = sqlite3.Row

    existing_instance_row = inventory_connection.execute(
        "SELECT identifier, provisioned_iops FROM db_instances WHERE identifier = ?",
        (instance_identifier,),
    ).fetchone()

    if existing_instance_row is None:
        inventory_connection.close()
        return {"success": False, "error": "instance not found in inventory"}

    current_provisioned_iops = existing_instance_row["provisioned_iops"] or 0
    new_provisioned_iops_total = current_provisioned_iops + additional_iops
    total_charge_amount_cents = additional_iops * price_per_iops_cents

    try:
        payment_charge_result = stripe.PaymentIntent.create(
            amount=total_charge_amount_cents,
            currency="usd",
            customer=customer_id,
            confirm=True,
            off_session=True,
            description="Provisioned IOPS for %s" % instance_identifier,
        )
    except stripe.error.StripeError as payment_error:
        inventory_connection.close()
        return {"success": False, "error": str(payment_error)}

    if payment_charge_result["status"] != "succeeded":
        inventory_connection.close()
        return {
            "success": False,
            "error": "payment status: %s" % payment_charge_result["status"],
            "charge_id": payment_charge_result["id"],
        }

    with inventory_connection:
        inventory_connection.execute(
            "UPDATE db_instances SET provisioned_iops = ? WHERE identifier = ?",
            (new_provisioned_iops_total, instance_identifier),
        )
    inventory_connection.close()

    return {
        "success": True,
        "charge_id": payment_charge_result["id"],
        "amount_cents": total_charge_amount_cents,
        "previous_iops": current_provisioned_iops,
        "new_iops": new_provisioned_iops_total,
    }
